# Use constraint folding to speed up: fold with hard constraint = target
# That gives MFE for the constrained fold but we need free MFE.

def fold(seq):
    fc=RNA.fold_compound(''.join(seq))
    s,mfe=fc.mfe()
    return s,mfe

def bp_dist(s):
    return sum(1 for i in range(n) if s[i]!=target[i])

